<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait TemplateVariableTenantAccessor
{
    private TemplateVariableTenantVO $_tenant;
    public function getTenant(): TenantRef
    {
        return $this->_tenant->value();
    }
    public function tenant(): TemplateVariableTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(TemplateVariableTenantVO|TenantRef $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = TemplateVariableTenantVO::from($tenant);
        return $copy;
    }
}
